#!/usr/bin/env bash
# Build the CA bundle that gets compiled into the console builds.
#
#   vendor/cacert/mkbundle.sh              download the current upstream bundle
#   vendor/cacert/mkbundle.sh cacert.pem   use a bundle already on disk
#   ALL_ROOTS=1 vendor/cacert/mkbundle.sh  take everything, ignoring roots.txt
#
# Output is vendor/cacert/data/cacert.bin, which is PEM text; the extension is
# what devkitPro's bin2s rule matches, and the directory holds that one file
# only because the platform Makefiles glob it.
#
# Re-run this when a root expires or an issuer changes. It is deliberately not
# wired into the build: a build that reaches the network to decide what it
# trusts is a build nobody can reproduce.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
out="$here/data/cacert.bin"
src="${1:-}"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

if [ -z "$src" ]; then
    src="$tmp/upstream.pem"
    echo "fetching https://curl.se/ca/cacert.pem"
    curl -fsS -o "$src" https://curl.se/ca/cacert.pem
fi

# Upstream is <label> / ==== rule / PEM block. Split it into one file per label
# so a root can be picked out by name rather than by line number.
awk -v dir="$tmp/certs" '
    /^={5,}$/ { label = prev; next }
    label != "" && /^-----BEGIN CERTIFICATE-----$/ { inside = 1 }
    inside { print > (dir "/" label ".pem") }
    inside && /^-----END CERTIFICATE-----$/ { inside = 0; label = "" }
    { prev = $0 }
' "$(mkdir -p "$tmp/certs" && echo "$src")"

{
    echo "# DaeMoon root bundle. Generated by vendor/cacert/mkbundle.sh."
    printf '# Source: https://curl.se/ca/cacert.pem%s\n' \
        "$(sed -n 's/^## Certificate data from Mozilla as of: /, Mozilla data of /p' "$src" | head -1)"
    echo "# Selection: vendor/cacert/roots.txt"
    echo
} > "$tmp/out.pem"

missing=0
count=0
if [ "${ALL_ROOTS:-0}" = "1" ]; then
    for f in "$tmp"/certs/*.pem; do
        label="$(basename "$f" .pem)"
        printf '%s\n' "$label" >> "$tmp/out.pem"
        cat "$f" >> "$tmp/out.pem"
        echo >> "$tmp/out.pem"
        count=$((count + 1))
    done
else
    while IFS= read -r label; do
        case "$label" in ''|'#'*) continue ;; esac
        if [ ! -f "$tmp/certs/$label.pem" ]; then
            echo "missing from upstream bundle: $label" >&2
            missing=$((missing + 1))
            continue
        fi
        printf '%s\n' "$label" >> "$tmp/out.pem"
        cat "$tmp/certs/$label.pem" >> "$tmp/out.pem"
        echo >> "$tmp/out.pem"
        count=$((count + 1))
    done < "$here/roots.txt"
fi

if [ "$missing" -ne 0 ]; then
    echo "$missing root(s) in roots.txt are no longer upstream; fix the list" >&2
    exit 1
fi

# Parse it back before it is anything the build can pick up. A bundle that
# looks like PEM and does not parse fails on hardware as tls_error, which is
# the one error message this whole file exists to stop somebody chasing.
if command -v openssl >/dev/null 2>&1; then
    parsed="$(grep -c '^-----BEGIN CERTIFICATE-----$' "$tmp/out.pem")"
    if [ "$parsed" -ne "$count" ]; then
        echo "expected $count certificates, bundle holds $parsed" >&2
        exit 1
    fi
    openssl crl2pkcs7 -nocrl -certfile "$tmp/out.pem" -out /dev/null
fi

mkdir -p "$(dirname "$out")"
mv "$tmp/out.pem" "$out"
echo "wrote $out: $count certificates, $(wc -c < "$out") bytes"
